--region define
local Lock   = "OverManegeLoungeMainDialog_BtnLounge_Lock"
local Normal = "OverManegeLoungeMainDialog_BtnLounge_Normal"
local Select = "OverManegeLoungeMainDialog_BtnLounge_Select"
local UISwitchImageType = typeof(CS.Game.Native.Common.UISwitchImage)
--endregion

