---@field ImgVIP                        	UnityEngine.RectTransform               
---@field TextNumber                    	TMPro.TextMeshProUGUI                   
---@field StatusRoom                    	UnityEngine.RectTransform               
---@field BtnLounge_Root                	UnityEngine.Animation                   
local OverManageBigBtnLoungeNode = Class('OverManageBigBtnLoungeNode')

function OverManageBigBtnLoungeNode:__init()
    self._statusRooms = {}
end

function OverManageBigBtnLoungeNode:__delete()

end

function OverManageBigBtnLoungeNode:Awake()

end

function OverManageBigBtnLoungeNode:Start()
    SetButtonAction(self.controller.gameObject, Bind(self, self.OnClickBtnAction))
end

function OverManageBigBtnLoungeNode:OnDestroy()

    self.controller = nil--luabehaviour 中CSharp
    self:Delete()
    self = nil
end

--region init

function OverManageBigBtnLoungeNode:InitUI(loungeData, index, isSelect)
    self.TextNumber.text = index
    self._index = index
    self:FreshUI(loungeData, isSelect)
end

--endregion


--region logic

---FreshUI
---@param loungeData table{
---    playerCardIds:table
---    roomId:number
---    loungeStatus:number
---}
function OverManageBigBtnLoungeNode:FreshUI(loungeData, isSelect)
    --self._loungeData = loungeData
    local playerCardIds       = loungeData.playerCardIds
    local parent             = self.StatusRoom

    local dataProviderIns    = DataProvider:GetInstance()
    for i, playerCardId in ipairs(playerCardIds) do
        local statusRoom = self._statusRooms[i]
        if isNull(statusRoom) then
            local child = parent:GetChild(i - 1)
            ---@type Game.Native.Common.UISwitchImage
            statusRoom = child.gameObject:GetComponent(UISwitchImageType)
            self._statusRooms[i] = statusRoom
        end
        statusRoom.Status = dataProviderIns:GetLoungeCardStatus(playerCardId)

    end
    
    local loungeStatus = loungeData.loungeStatus
    KTool.SetActive(self.ImgVIP.gameObject, loungeStatus == MaidCoffeeConstants.LoungeStatus.VipLock or loungeStatus == MaidCoffeeConstants.LoungeStatus.VipUnlock)
    
    self:FreshNodeStatus(loungeStatus, isSelect)
    
    
end

function OverManageBigBtnLoungeNode:FreshNodeStatus(loungeStatus, isSelect)
    local aniName = Normal
    if isSelect then
        aniName = Select
    elseif loungeStatus == MaidCoffeeConstants.LoungeStatus.VipLock or MaidCoffeeConstants.LoungeStatus.Lock == loungeStatus then
        aniName = Lock
    end

    self.BtnLounge_Root:Play(aniName)
end

--endregion


--region get/set

function OverManageBigBtnLoungeNode:SetCallback(cb)
    self._callback = cb
end

--endregion


--region handler

function OverManageBigBtnLoungeNode:OnClickBtnAction()
    if self._callback then
        self._callback(self._index)
    end
end

--endregion

return OverManageBigBtnLoungeNode